import { createClient } from '@supabase/supabase-js';
import { publicSupabaseEnvironment } from './config/publicEnvironment';

const supabaseUrl = publicSupabaseEnvironment.url;
const supabaseAnonKey = publicSupabaseEnvironment.key;

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    // Mantém a sessão e permite sua renovação automática entre aberturas do app.
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
  },
});

const AUTH_REFRESH_LEEWAY_SECONDS = 90;

type AuthFetchGlobal = typeof globalThis & {
  __evolucaoClinicaAuthenticatedFetchInstalled?: boolean;
};

let refreshInFlight: Promise<string | null> | null = null;

const refreshAccessToken = async (): Promise<string | null> => {
  if (refreshInFlight) return refreshInFlight;

  refreshInFlight = (async () => {
    try {
      const { data, error } = await supabase.auth.refreshSession();
      if (error) {
        console.warn('[Auth] Não foi possível renovar a sessão automaticamente:', error.message);
        return null;
      }
      return data.session?.access_token || null;
    } catch (error) {
      console.warn('[Auth] Falha inesperada ao renovar a sessão automaticamente:', error);
      return null;
    } finally {
      refreshInFlight = null;
    }
  })();

  return refreshInFlight;
};

const getFreshAccessToken = async (forceRefresh = false): Promise<string | null> => {
  try {
    if (forceRefresh) {
      return await refreshAccessToken();
    }

    const { data, error } = await supabase.auth.getSession();
    if (error) {
      console.warn('[Auth] Não foi possível ler a sessão atual:', error.message);
      return null;
    }

    const session = data.session;
    if (!session?.access_token) return null;

    const expiresAt = Number(session.expires_at || 0);
    const nowSeconds = Math.floor(Date.now() / 1000);
    const closeToExpiry = expiresAt > 0 && expiresAt <= nowSeconds + AUTH_REFRESH_LEEWAY_SECONDS;

    if (closeToExpiry) {
      return (await refreshAccessToken()) || session.access_token;
    }

    return session.access_token;
  } catch (error) {
    console.warn('[Auth] Falha inesperada ao obter token autenticado:', error);
    return null;
  }
};

const installAuthenticatedApiFetch = () => {
  if (typeof window === 'undefined' || typeof globalThis.fetch !== 'function') return;

  const authGlobal = globalThis as AuthFetchGlobal;
  if (authGlobal.__evolucaoClinicaAuthenticatedFetchInstalled) return;
  authGlobal.__evolucaoClinicaAuthenticatedFetchInstalled = true;

  const nativeFetch = globalThis.fetch.bind(globalThis);

  globalThis.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    let baseRequest: Request;

    try {
      baseRequest = new Request(input, init);
    } catch {
      return nativeFetch(input, init);
    }

    let requestUrl: URL;
    try {
      requestUrl = new URL(baseRequest.url, window.location.href);
    } catch {
      return nativeFetch(input, init);
    }

    const authorization = baseRequest.headers.get('Authorization') || '';
    const hasBearer = /^Bearer\s+.+$/i.test(authorization);
    const isOwnApi =
      requestUrl.origin === window.location.origin &&
      requestUrl.pathname.startsWith('/api/');

    // Só interfere nas chamadas autenticadas da própria plataforma.
    // Requisições públicas e chamadas externas continuam usando fetch nativo.
    if (!isOwnApi || !hasBearer) {
      return nativeFetch(input, init);
    }

    const capturedToken = authorization.replace(/^Bearer\s+/i, '').trim();

    const buildRequest = (token: string) => {
      const headers = new Headers(baseRequest.headers);
      headers.set('Authorization', `Bearer ${token}`);
      return new Request(baseRequest.clone(), { headers });
    };

    try {
      // Mesmo que a tela tenha guardado um token antigo em estado React,
      // substitui pelo token atual da sessão antes de enviar a requisição.
      const currentToken = await getFreshAccessToken(false);
      const firstToken = currentToken || capturedToken;
      const response = await nativeFetch(buildRequest(firstToken));

      if (response.status !== 401) {
        return response;
      }

      // Uma única tentativa de recuperação: renova a sessão e repete a chamada.
      // Se o refresh realmente falhar, devolve o 401 original e o fluxo normal
      // pode redirecionar o usuário ao login.
      const refreshedToken = await getFreshAccessToken(true);
      if (!refreshedToken) {
        return response;
      }

      return await nativeFetch(buildRequest(refreshedToken));
    } catch (error) {
      console.warn('[Auth] Falha no retry autenticado; usando requisição original:', error);
      return nativeFetch(input, init);
    }
  };
};

installAuthenticatedApiFetch();

export default supabase;

src/utils/acquisitionAttribution.ts:
export interface AcquisitionData {
  utm_source?: string;
  utm_medium?: string;
  utm_campaign?: string;
  utm_term?: string;
  utm_content?: string;
  gclid?: string;
  fbclid?: string;
  referrer?: string;
  landing_page?: string;
  first_seen_at?: string;
  channel?: string;
  attribution_method?: 'url' | 'google_play_install_referrer';
  referrer_click_at?: string;
  install_begin_at?: string;
  platform?: 'web' | 'pwa' | 'android';
  distribution?: 'google_play';
}

const PAID_MEDIA = new Set(['cpc', 'ppc', 'paid', 'paid_social', 'social_paid']);
const ORGANIC_SOCIAL_MEDIA = new Set(['organic', 'organic_social', 'social', 'bio', 'profile']);
const TECHNICAL_PLATFORM_MARKERS = new Set(['pwa', 'android', 'app', 'mobile', 'google_play', 'google-play']);
const TRACKING_QUERY_KEYS = new Set([
  'utm_source',
  'utm_medium',
  'utm_campaign',
  'utm_term',
  'utm_content',
  'gclid',
  'fbclid',
  'msclkid',
  'ttclid'
]);

const normalize = (value?: string | null) => (value || '').trim().toLowerCase();

export const normalizeAcquisitionSource = (value?: string | null): string => {
  const source = normalize(value);
  if (source === 'ig') return 'instagram';
  if (source === 'fb') return 'facebook';
  if (source === 'facebook_ads') return 'meta';
  if (source === 'meta_ads') return 'meta';
  if (source === 'google_ads') return 'google';
  return source;
};

export const normalizeAcquisitionMedium = (value?: string | null): string => normalize(value);

export const isTechnicalPlatformMarker = (value?: string | null): boolean => (
  TECHNICAL_PLATFORM_MARKERS.has(normalize(value))
);

const safeHostname = (value?: string | null): string => {
  if (!value) return '';
  try {
    return new URL(value).hostname.toLowerCase();
  } catch {
    return '';
  }
};

export const isValidAcquisitionData = (value: unknown): value is AcquisitionData => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const data = value as AcquisitionData;
  return Boolean(
    data.utm_source ||
      data.utm_medium ||
      data.utm_campaign ||
      data.gclid ||
      data.fbclid ||
      data.referrer ||
      data.landing_page ||
      data.channel ||
      data.platform ||
      data.distribution
  );
};

export const hasAttributableSignal = (data: AcquisitionData): boolean => {
  const source = normalizeAcquisitionSource(data.utm_source);
  const medium = normalizeAcquisitionMedium(data.utm_medium);
  const technicalSource = isTechnicalPlatformMarker(source);
  return Boolean(
    (source && source !== 'direct' && !technicalSource) ||
    (medium && medium !== 'direct' && !isTechnicalPlatformMarker(medium) && !(technicalSource && medium === 'organic')) ||
    data.utm_campaign ||
    data.utm_term ||
    data.utm_content ||
    data.gclid ||
    data.fbclid ||
    data.referrer
  );
};

export const isGenericAppFallback = (data?: AcquisitionData | null): boolean => {
  const source = normalizeAcquisitionSource(data?.utm_source);
  const medium = normalizeAcquisitionMedium(data?.utm_medium);
  return (isTechnicalPlatformMarker(source) || isTechnicalPlatformMarker(medium))
    && !hasAttributableSignal(data || {});
};

export function calculateAcquisitionChannel(data: AcquisitionData): string {
  const source = normalizeAcquisitionSource(data.utm_source);
  const medium = normalizeAcquisitionMedium(data.utm_medium);
  const referrerHost = safeHostname(data.referrer);
  const isPaid = PAID_MEDIA.has(medium);

  // O gclid é um identificador emitido pelo Google Ads. Ele prevalece sobre
  // fontes genéricas que o Google Play possa anexar ao install referrer.
  if (data.gclid) return 'Google Ads (Tráfego Pago)';

  if (source === 'google') {
    if (isPaid) return 'Google Ads (Tráfego Pago)';
    return 'Google (Busca Orgânica)';
  }

  if (source === 'instagram') {
    if (isPaid) return 'Meta Ads (Instagram)';
    if (medium === 'bio' || medium === 'profile') return 'Instagram (Link na Bio)';
    return 'Instagram (Orgânico/Social)';
  }

  if (source === 'facebook') {
    if (isPaid) return 'Meta Ads (Facebook)';
    return 'Facebook (Orgânico/Social)';
  }

  if (source === 'meta') {
    return isPaid ? 'Meta Ads (Tráfego Pago)' : 'Meta (Social)';
  }

  if (source === 'youtube') return 'YouTube';
  if (source === 'whatsapp' || medium === 'whatsapp') return 'WhatsApp';
  if (source === 'email' || medium === 'email') return 'E-mail';
  if (source === 'direct') return 'Tráfego Direto';

  if (source && !isTechnicalPlatformMarker(source)) {
    if (isPaid) return `${source.toUpperCase()} (Tráfego Pago)`;
    if (ORGANIC_SOCIAL_MEDIA.has(medium)) return `${source.toUpperCase()} (Orgânico/Social)`;
    return `${source.toUpperCase()}${medium ? ` (${medium})` : ''}`;
  }

  if (referrerHost.includes('instagram.com')) return 'Instagram (Orgânico/Social)';
  if (referrerHost.includes('facebook.com')) return 'Facebook (Orgânico/Social)';
  if (referrerHost.includes('google.')) return 'Google (Busca Orgânica)';
  if (referrerHost.includes('youtube.com') || referrerHost.includes('youtu.be')) return 'YouTube';

  if (data.fbclid) {
    return 'Meta / Facebook (Origem não determinada)';
  }

  if (data.referrer) return `Referral (${referrerHost || 'site externo'})`;
  if (isGenericAppFallback(data)) return 'Origem não informada';
  if (data.utm_campaign || data.utm_term || data.utm_content || (medium && !isTechnicalPlatformMarker(medium))) {
    return isPaid ? 'Mídia paga (origem não informada)' : 'Campanha (origem não informada)';
  }
  if (isTechnicalPlatformMarker(source) || isTechnicalPlatformMarker(medium)) return 'Origem não informada';
  return 'Tráfego Direto';
}

export const normalizeAcquisitionCandidate = (data: AcquisitionData): AcquisitionData => {
  const normalized: AcquisitionData = { ...data };
  const technicalSource = isTechnicalPlatformMarker(normalized.utm_source);
  if (technicalSource) delete normalized.utm_source;
  if (isTechnicalPlatformMarker(normalized.utm_medium) || (technicalSource && normalize(normalized.utm_medium) === 'organic')) {
    delete normalized.utm_medium;
  }
  normalized.channel = calculateAcquisitionChannel(normalized);
  return normalized;
};

export const getAcquisitionPlatform = (data?: AcquisitionData | null): AcquisitionData['platform'] | undefined => {
  if (data?.platform === 'web' || data?.platform === 'pwa' || data?.platform === 'android') return data.platform;
  if (normalize(data?.utm_source) === 'pwa' || normalize(data?.utm_medium) === 'pwa') return 'pwa';
  if (normalize(data?.utm_source) === 'android' || normalize(data?.utm_medium) === 'android') return 'android';
  if (data?.attribution_method === 'google_play_install_referrer') return 'android';
  return undefined;
};

export const getAcquisitionDistribution = (
  data?: AcquisitionData | null
): AcquisitionData['distribution'] | undefined => {
  if (data?.distribution === 'google_play') return data.distribution;
  if (data?.attribution_method === 'google_play_install_referrer') return 'google_play';
  return undefined;
};

export const getAcquisitionChannelLabel = (data?: AcquisitionData | null): string => (
  data && isValidAcquisitionData(data) ? calculateAcquisitionChannel(data) : 'Origem não informada'
);

const mergeAccessContext = (touch: AcquisitionData, access: AcquisitionData): AcquisitionData => ({
  ...touch,
  ...(access.platform ? { platform: access.platform } : {}),
  ...(access.distribution ? { distribution: access.distribution } : {}),
});

export const sanitizeTrackingUrl = (rawUrl?: string | null, baseOrigin?: string): string | undefined => {
  if (!rawUrl) return undefined;

  try {
    const url = baseOrigin ? new URL(rawUrl, baseOrigin) : new URL(rawUrl);
    const sanitized = new URL(`${url.origin}${url.pathname}`);

    url.searchParams.forEach((value, key) => {
      if (TRACKING_QUERY_KEYS.has(key.toLowerCase())) {
        sanitized.searchParams.set(key, value);
      }
    });

    return sanitized.toString();
  } catch {
    return undefined;
  }
};

export const resolveAcquisitionTouches = ({
  existingFirstTouch,
  existingCurrentTouch,
  candidate,
  returningFromOAuth,
}: {
  existingFirstTouch?: AcquisitionData | null;
  existingCurrentTouch?: AcquisitionData | null;
  candidate: AcquisitionData;
  returningFromOAuth: boolean;
}): { firstTouch: AcquisitionData; currentTouch: AcquisitionData } => {
  const candidateReplacesAppFallback = hasAttributableSignal(candidate) && !isGenericAppFallback(candidate);
  const candidateResolvesNativeInstall = candidate.attribution_method === 'google_play_install_referrer'
    && hasAttributableSignal(candidate)
    && getAcquisitionPlatform(existingFirstTouch) === 'android'
    && !hasAttributableSignal(existingFirstTouch || {});

  const firstTouch = existingFirstTouch
    && !(isGenericAppFallback(existingFirstTouch) && candidateReplacesAppFallback)
    && !candidateResolvesNativeInstall
    ? existingFirstTouch
    : candidate;

  let currentTouch = candidate;
  if (
    existingCurrentTouch
    && !isGenericAppFallback(existingCurrentTouch)
    && (returningFromOAuth || !hasAttributableSignal(candidate))
  ) {
    // OAuth, reload e uma abertura direta pelo app atualizam somente o contexto
    // técnico. A última origem real de marketing continua sendo o signup touch.
    currentTouch = mergeAccessContext(existingCurrentTouch, candidate);
  }

  return { firstTouch, currentTouch };
};

export const shouldPersistFirstTouch = (
  persisted?: AcquisitionData | null,
  candidate?: AcquisitionData | null
): boolean => {
  if (!candidate || !isValidAcquisitionData(candidate)) return false;
  if (!persisted || !isValidAcquisitionData(persisted)) return true;
  return (isGenericAppFallback(persisted) && hasAttributableSignal(candidate)) || (
    candidate.attribution_method === 'google_play_install_referrer'
    && hasAttributableSignal(candidate)
    && getAcquisitionPlatform(persisted) === 'android'
    && !hasAttributableSignal(persisted)
  );
};

export const shouldPersistSignupTouch = shouldPersistFirstTouch;

export const isLikelyOAuthReturn = (rawUrl?: string | null, referrer?: string | null): boolean => {
  try {
    if (rawUrl) {
      const url = new URL(rawUrl);
      const callbackKeys = [
        'code',
        'state',
        'access_token',
        'refresh_token',
        'id_token',
        'error',
        'error_description'
      ];
      if (callbackKeys.some((key) => url.searchParams.has(key) || url.hash.includes(`${key}=`))) {
        return true;
      }
    }
  } catch {
    // URL inválida não deve interferir no tracking.
  }

  const referrerHost = safeHostname(referrer);
  return referrerHost.includes('accounts.google.com') || referrerHost.includes('supabase.co');
};

src/utils/acquisitionTracking.ts:
import { supabase } from '../supabaseClient';
import { getConsentPreferences } from '../services/analytics';
import {
  type AcquisitionData,
  calculateAcquisitionChannel,
  hasAttributableSignal,
  isLikelyOAuthReturn,
  isValidAcquisitionData,
  normalizeAcquisitionCandidate,
  resolveAcquisitionTouches,
  sanitizeTrackingUrl,
  shouldPersistFirstTouch,
  shouldPersistSignupTouch,
} from './acquisitionAttribution';
import { getInstalledAppInfo } from './installedAppInfo';

export type { AcquisitionData } from './acquisitionAttribution';
export { calculateAcquisitionChannel } from './acquisitionAttribution';

const LEGACY_STORAGE_KEY = 'evolucao-clinica:acquisition';
const FIRST_TOUCH_STORAGE_KEY = 'evolucao-clinica:acquisition:first-touch';
const CURRENT_TOUCH_STORAGE_KEY = 'evolucao-clinica:acquisition:current-touch';
const SIGNUP_PENDING_PREFIX = 'evolucao-clinica:acquisition:signup-pending';
const NEW_ACCOUNT_WINDOW_MS = 2 * 60 * 60 * 1000;
const NATIVE_REFERRER_ATTEMPTS = 10;
const NATIVE_REFERRER_RETRY_MS = 300;

type NativeInstallAttributionPayload = {
  status?: 'pending' | 'ready' | 'unavailable';
  install_referrer?: string;
  referrer_click_timestamp_seconds?: number;
  install_begin_timestamp_seconds?: number;
};

declare global {
  interface Window {
    NativeAcquisitionBridge?: {
      getInstallAttribution: () => string;
      requestInstallAttribution: () => void;
    };
  }
}

const safeRead = (key: string): AcquisitionData | null => {
  if (typeof window === 'undefined') return null;
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return isValidAcquisitionData(parsed) ? parsed : null;
  } catch (error) {
    console.warn('[AcquisitionTracking] Não foi possível ler dados locais de aquisição.', error);
    return null;
  }
};

const safeWrite = (key: string, data: AcquisitionData): void => {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(key, JSON.stringify(data));
  } catch (error) {
    console.warn('[AcquisitionTracking] Não foi possível persistir dados locais de aquisição.', error);
  }
};

const safeRemove = (key: string): void => {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.removeItem(key);
  } catch {
    // Falha de limpeza não pode afetar autenticação ou navegação.
  }
};

const getSignupPendingKey = (userId: string) => `${SIGNUP_PENDING_PREFIX}:${userId}`;

const readFirstTouch = (): AcquisitionData | null => {
  const current = safeRead(FIRST_TOUCH_STORAGE_KEY);
  if (current) return current;

  const legacy = safeRead(LEGACY_STORAGE_KEY);
  if (legacy) {
    safeWrite(FIRST_TOUCH_STORAGE_KEY, legacy);
    return legacy;
  }

  return null;
};

const buildCurrentTouch = (): AcquisitionData => {
  const urlParams = new URLSearchParams(window.location.search);
  const accessPlatform = getInstalledAppInfo().platform;
  const externalReferrer = document.referrer && !document.referrer.includes(window.location.hostname)
    ? sanitizeTrackingUrl(document.referrer)
    : undefined;

  const data: AcquisitionData = {
    utm_source: urlParams.get('utm_source') || undefined,
    utm_medium: urlParams.get('utm_medium') || undefined,
    utm_campaign: urlParams.get('utm_campaign') || undefined,
    utm_term: urlParams.get('utm_term') || undefined,
    utm_content: urlParams.get('utm_content') || undefined,
    gclid: urlParams.get('gclid') || undefined,
    fbclid: urlParams.get('fbclid') || undefined,
    referrer: externalReferrer,
    landing_page: sanitizeTrackingUrl(window.location.href, window.location.origin),
    first_seen_at: new Date().toISOString(),
    attribution_method: 'url',
  };

  data.platform = accessPlatform;
  return normalizeAcquisitionCandidate(data);
};

const persistAcquisitionCandidate = (
  candidate: AcquisitionData,
  returningFromOAuth = false
): AcquisitionData => {
  const existingFirstTouch = readFirstTouch();
  const existingCurrentTouch = safeRead(CURRENT_TOUCH_STORAGE_KEY);
  const { firstTouch, currentTouch } = resolveAcquisitionTouches({
    existingFirstTouch,
    existingCurrentTouch,
    candidate,
    returningFromOAuth,
  });

  if (!existingFirstTouch || firstTouch !== existingFirstTouch) {
    safeWrite(FIRST_TOUCH_STORAGE_KEY, firstTouch);
    safeWrite(LEGACY_STORAGE_KEY, firstTouch);
  }

  safeWrite(CURRENT_TOUCH_STORAGE_KEY, currentTouch);
  return firstTouch;
};

/**
 * Captura first touch e o touch da sessão atual.
 * O first touch é imutável; o current touch é atualizado a cada nova sessão,
 * exceto no retorno de OAuth, quando preservamos a origem anterior.
 */
export function captureAcquisitionData(): AcquisitionData {
  if (typeof window === 'undefined') return {};

  const candidate = buildCurrentTouch();

  const pendingOAuth = Boolean(
    window.localStorage.getItem('oauth_redirect_path') ||
    window.localStorage.getItem('evolucao-clinica:google-oauth-scopes')
  );
  const returningFromOAuth = isLikelyOAuthReturn(window.location.href, document.referrer) || pendingOAuth;
  return persistAcquisitionCandidate(candidate, returningFromOAuth);
}

const timestampSecondsToIso = (value?: number): string | undefined => {
  if (!Number.isFinite(value) || Number(value) <= 0) return undefined;
  return new Date(Number(value) * 1000).toISOString();
};

const nativePayloadToAcquisition = (payload: NativeInstallAttributionPayload): AcquisitionData | null => {
  if (payload.status !== 'ready' || !payload.install_referrer) return null;

  const params = new URLSearchParams(payload.install_referrer.replace(/^\?/, ''));
  const data: AcquisitionData = {
    utm_source: params.get('utm_source') || undefined,
    utm_medium: params.get('utm_medium') || undefined,
    utm_campaign: params.get('utm_campaign') || undefined,
    utm_term: params.get('utm_term') || undefined,
    utm_content: params.get('utm_content') || undefined,
    gclid: params.get('gclid') || undefined,
    fbclid: params.get('fbclid') || undefined,
    landing_page: typeof window !== 'undefined'
      ? sanitizeTrackingUrl(window.location.href, window.location.origin)
      : undefined,
    first_seen_at: timestampSecondsToIso(payload.referrer_click_timestamp_seconds) || new Date().toISOString(),
    attribution_method: 'google_play_install_referrer',
    referrer_click_at: timestampSecondsToIso(payload.referrer_click_timestamp_seconds),
    install_begin_at: timestampSecondsToIso(payload.install_begin_timestamp_seconds),
    platform: 'android',
    distribution: 'google_play',
  };

  return normalizeAcquisitionCandidate(data);
};

const wait = (milliseconds: number) => new Promise(resolve => window.setTimeout(resolve, milliseconds));
let nativeAttributionPromise: Promise<AcquisitionData | null> | null = null;

/**
 * Recupera a referência de instalação do Google Play no aplicativo Android.
 * O bridge devolve somente o conteúdo oficial do Install Referrer; a aplicação
 * persiste apenas UTMs e click IDs já aceitos pelo modelo de aquisição.
 */
export function captureNativeInstallAttribution(): Promise<AcquisitionData | null> {
  if (
    typeof window === 'undefined'
    || getConsentPreferences()?.marketing !== true
    || !window.NativeAcquisitionBridge?.getInstallAttribution
  ) {
    return Promise.resolve(null);
  }
  if (nativeAttributionPromise) return nativeAttributionPromise;

  nativeAttributionPromise = (async () => {
    window.NativeAcquisitionBridge?.requestInstallAttribution();
    for (let attempt = 0; attempt < NATIVE_REFERRER_ATTEMPTS; attempt += 1) {
      try {
        const raw = window.NativeAcquisitionBridge?.getInstallAttribution();
        const payload = raw ? JSON.parse(raw) as NativeInstallAttributionPayload : null;
        const acquisition = payload ? nativePayloadToAcquisition(payload) : null;
        if (acquisition) {
          persistAcquisitionCandidate(acquisition);
          return acquisition;
        }
        if (payload?.status === 'unavailable') return null;
      } catch (error) {
        console.warn('[AcquisitionTracking] Referência nativa de instalação inválida.', error);
        return null;
      }
      await wait(NATIVE_REFERRER_RETRY_MS);
    }
    return null;
  })();

  return nativeAttributionPromise;
}

/**
 * Compatibilidade: retorna o first touch.
 */
export function getLocalAcquisitionData(): AcquisitionData {
  return readFirstTouch() || captureAcquisitionData();
}

export function getCurrentAcquisitionData(): AcquisitionData {
  if (typeof window === 'undefined') return {};
  const stored = safeRead(CURRENT_TOUCH_STORAGE_KEY);
  if (stored) return stored;
  captureAcquisitionData();
  return safeRead(CURRENT_TOUCH_STORAGE_KEY) || getLocalAcquisitionData();
}

const isRecentlyCreatedAccount = (createdAt?: string | null): boolean => {
  if (!createdAt) return false;
  const createdAtMs = new Date(createdAt).getTime();
  if (!Number.isFinite(createdAtMs)) return false;
  return Date.now() - createdAtMs >= 0 && Date.now() - createdAtMs <= NEW_ACCOUNT_WINDOW_MS;
};

const isMissingColumnError = (message?: string | null, columnName?: string): boolean => {
  const normalized = String(message || '').toLowerCase();
  if (!columnName) return false;
  return normalized.includes(columnName.toLowerCase()) && (
    normalized.includes('column') ||
    normalized.includes('schema cache') ||
    normalized.includes('does not exist')
  );
};

/**
 * Sincroniza first touch e signup touch com o perfil no Supabase.
 * Tracking é best-effort: falhas nunca bloqueiam login/onboarding.
 */
export async function syncAcquisitionWithDatabase(
  userId: string,
  currentInfo?: AcquisitionData | null
): Promise<void> {
  if (!userId) return;

  const firstTouch = getLocalAcquisitionData();
  const currentTouch = getCurrentAcquisitionData();

  try {
    if (shouldPersistFirstTouch(currentInfo, firstTouch)) {
      const { error } = await supabase
        .from('professionals')
        .update({ acquisition_info: firstTouch })
        .eq('id', userId);

      if (error) {
        console.warn('[AcquisitionTracking] Falha ao registrar first touch:', error.message);
      }
    }

    const pendingKey = getSignupPendingKey(userId);
    let pendingSignupTouch = safeRead(pendingKey);

    if (!pendingSignupTouch) {
      const { data: authData } = await supabase.auth.getUser();
      const authUser = authData?.user;
      if (authUser?.id === userId && isRecentlyCreatedAccount(authUser.created_at) && isValidAcquisitionData(currentTouch)) {
        pendingSignupTouch = currentTouch;
        safeWrite(pendingKey, currentTouch);
      }
    }

    if (!pendingSignupTouch) return;

    const { data: profile, error: profileError } = await supabase
      .from('professionals')
      .select('signup_acquisition_info')
      .eq('id', userId)
      .maybeSingle();

    if (profileError) {
      if (!isMissingColumnError(profileError.message, 'signup_acquisition_info')) {
        console.warn('[AcquisitionTracking] Falha ao consultar signup touch:', profileError.message);
      }
      return;
    }

    if (!shouldPersistSignupTouch(profile?.signup_acquisition_info, pendingSignupTouch)) {
      safeRemove(pendingKey);
      return;
    }

    const { error: signupError } = await supabase
      .from('professionals')
      .update({ signup_acquisition_info: pendingSignupTouch })
      .eq('id', userId);

    if (signupError) {
      if (!isMissingColumnError(signupError.message, 'signup_acquisition_info')) {
        console.warn('[AcquisitionTracking] Falha ao registrar signup touch:', signupError.message);
      }
      return;
    }

    safeRemove(pendingKey);
  } catch (error) {
    console.warn('[AcquisitionTracking] Sincronização de aquisição indisponível; acesso preservado.', error);
  }
}

export const __acquisitionTrackingInternals = {
  LEGACY_STORAGE_KEY,
  FIRST_TOUCH_STORAGE_KEY,
  CURRENT_TOUCH_STORAGE_KEY,
  SIGNUP_PENDING_PREFIX,
  hasAttributableSignal,
};

