src/utils/horizontalSwipe.ts:
export type HorizontalSwipeDirection = 'next' | 'previous';

type HorizontalSwipeMeasurement = {
  deltaX: number;
  deltaY: number;
};

const SHORT_SWIPE_DISTANCE_PX = 14;
const HORIZONTAL_AXIS_TOLERANCE = 0.65;

export const resolveHorizontalSwipe = ({
  deltaX,
  deltaY,
}: HorizontalSwipeMeasurement): HorizontalSwipeDirection | null => {
  const absX = Math.abs(deltaX);
  const absY = Math.abs(deltaY);
  const hasHorizontalIntent = absX >= absY * HORIZONTAL_AXIS_TOLERANCE;

  if (!hasHorizontalIntent || absX < SHORT_SWIPE_DISTANCE_PX) {
    return null;
  }

  return deltaX < 0 ? 'next' : 'previous';
};

src/utils/installedAppInfo.ts:
export interface InstalledAppInfo {
  platform: 'android' | 'pwa' | 'web';
  versionCode: number | null;
  versionName: string | null;
  displayVersion: string | null;
}

declare global {
  interface Window {
    NativeAppInfoBridge?: {
      getAppInfo?: () => string;
      setPullToRefreshEnabled?: (enabled: boolean) => void;
      checkForUpdate?: () => void;
      openPlayStore?: () => void;
    };
  }
}

const parsePositiveInteger = (value: unknown): number | null => {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const NATIVE_VERSION_STORAGE_KEY = 'evolucao-clinica:native-version-code';

const readLaunchVersionCode = (): number | null => {
  if (typeof window === 'undefined') return null;

  try {
    const queryVersion = new URLSearchParams(window.location.search).get('native_version');
    return parsePositiveInteger(queryVersion);
  } catch {
    return null;
  }
};

const readStoredLaunchVersionCode = (): number | null => {
  if (typeof window === 'undefined') return null;

  try {
    return parsePositiveInteger(window.sessionStorage.getItem(NATIVE_VERSION_STORAGE_KEY));
  } catch {
    return null;
  }
};

export const formatPlayStoreVersion = (versionCode: number | null, versionName?: string | null) => {
  const normalizedName = String(versionName ?? '').trim();
  const cleanName = normalizedName.replace(/^v/i, '');

  // O Android pode expor o versionName como "55" ou como "1.0.55".
  // O nome é a versão que o usuário reconhece; o versionCode permanece
  // disponível separadamente para conferir divergências no Play Console.
  if (/^\d+$/.test(cleanName)) return `1.0.${cleanName}`;
  if (/^\d+(?:\.\d+){1,3}$/.test(cleanName)) return cleanName;
  if (versionCode) return `1.0.${versionCode}`;
  return cleanName || null;
};

const readNativeBridge = (): InstalledAppInfo | null => {
  if (typeof window === 'undefined' || !window.NativeAppInfoBridge?.getAppInfo) return null;

  try {
    const payload = JSON.parse(window.NativeAppInfoBridge.getAppInfo()) as {
      versionCode?: unknown;
      versionName?: unknown;
    };
    const versionCode = parsePositiveInteger(payload.versionCode);
    const versionName = String(payload.versionName ?? '').trim() || null;

    return {
      platform: 'android',
      versionCode,
      versionName,
      displayVersion: formatPlayStoreVersion(versionCode, versionName)
    };
  } catch (error) {
    console.warn('[AppInfo] Não foi possível ler a versão pelo bridge nativo.', error);
    return null;
  }
};

const readNativeUserAgent = (): InstalledAppInfo | null => {
  if (typeof navigator === 'undefined') return null;

  const match = navigator.userAgent.match(/EvolucaoClinicaApp\/([^\s;]+)/i);
  if (!match) return null;

  const versionName = match[1];
  const numericParts = versionName.match(/\d+/g);
  const versionCode = parsePositiveInteger(numericParts?.at(-1));

  return {
    platform: 'android',
    versionCode,
    versionName,
    displayVersion: formatPlayStoreVersion(versionCode, versionName)
  };
};

export const getInstalledAppInfo = (): InstalledAppInfo => {
  // A ponte consulta o PackageManager em tempo real e, por isso, é a fonte
  // mais confiável após uma atualização feita pela Play Store. Um parâmetro
  // ou dado de sessão pode pertencer à execução anterior do WebView.
  const nativeBridgeInfo = readNativeBridge();
  if (nativeBridgeInfo) return nativeBridgeInfo;

  const launchVersionCode = readLaunchVersionCode();
  const storedLaunchVersionCode = readStoredLaunchVersionCode();
  const nativeUserAgentInfo = readNativeUserAgent();

  if (launchVersionCode || storedLaunchVersionCode || nativeUserAgentInfo) {
    // A URL atual identifica o lançamento do app. O valor persistido serve
    // apenas de contingência para navegações SPA, quando a ponte nativa não
    // está disponível (por exemplo, em instalações antigas).
    const versionCode = launchVersionCode || storedLaunchVersionCode || nativeUserAgentInfo?.versionCode || null;
    const versionName = launchVersionCode || storedLaunchVersionCode
      ? String(versionCode)
      : nativeUserAgentInfo?.versionName || null;

    return {
      platform: 'android',
      versionCode,
      versionName,
      displayVersion: formatPlayStoreVersion(versionCode, versionName)
    };
  }

  const isPwa = typeof window !== 'undefined' && (
    window.matchMedia('(display-mode: standalone)').matches ||
    Boolean((window.navigator as Navigator & { standalone?: boolean }).standalone)
  );

  return {
    platform: isPwa ? 'pwa' : 'web',
    versionCode: null,
    versionName: null,
    displayVersion: null
  };
};

src/utils/lazyWithRetry.ts:
import React, { lazy } from 'react';

const LAZY_RETRY_PREFIX = 'evolucao-clinica:lazy-retry';
const RETRY_QUERY_PARAM = '__lazy_retry';
const APP_CACHE_PREFIX = 'evolucao-clinica-pwa-';

const RETRYABLE_CHUNK_PATTERNS = [
  /Failed to fetch dynamically imported module/i,
  /Importing a module script failed/i,
  /error loading dynamically imported module/i,
  /Failed to load module script/i,
  /Expected a JavaScript(?:-or-Wasm)? module script/i,
  /MIME type.*text\/html/i,
  /ChunkLoadError/i,
];

export const isRetryableChunkError = (error: unknown) => {
  const message = error instanceof Error
    ? `${error.name} ${error.message}`
    : String(error || '');

  return RETRYABLE_CHUNK_PATTERNS.some((pattern) => pattern.test(message));
};

const clearAppCaches = async () => {
  if (typeof window === 'undefined' || !('caches' in window)) return;

  const cacheNames = await window.caches.keys();
  await Promise.all(
    cacheNames
      .filter((cacheName) => cacheName.startsWith(APP_CACHE_PREFIX))
      .map((cacheName) => window.caches.delete(cacheName))
  );
};

const buildRetryUrl = () => {
  const url = new URL(window.location.href);
  url.searchParams.set(RETRY_QUERY_PARAM, Date.now().toString());
  return url.toString();
};

const reloadWithCurrentBuild = async () => {
  try {
    await clearAppCaches();
  } catch (error) {
    console.warn('[ChunkRecovery] Não foi possível limpar o cache PWA.', error);
  }

  window.location.replace(buildRetryUrl());
};

export const attemptChunkRecovery = async (error: unknown, chunkName: string) => {
  if (typeof window === 'undefined' || !isRetryableChunkError(error)) return false;

  const retryKey = `${LAZY_RETRY_PREFIX}:${chunkName}`;
  if (window.sessionStorage.getItem(retryKey) === '1') return false;

  window.sessionStorage.setItem(retryKey, '1');
  await reloadWithCurrentBuild();
  return true;
};

export const forceChunkRecovery = async () => {
  if (typeof window === 'undefined') return;

  for (let index = window.sessionStorage.length - 1; index >= 0; index -= 1) {
    const key = window.sessionStorage.key(index);
    if (key?.startsWith(LAZY_RETRY_PREFIX)) {
      window.sessionStorage.removeItem(key);
    }
  }

  await reloadWithCurrentBuild();
};

export const installGlobalChunkRecovery = () => {
  if (typeof window === 'undefined') return () => undefined;

  const handleWindowError = (event: ErrorEvent) => {
    const error = event.error || event.message;
    if (!isRetryableChunkError(error)) return;

    event.preventDefault();
    void attemptChunkRecovery(error, 'global');
  };

  const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
    if (!isRetryableChunkError(event.reason)) return;

    event.preventDefault();
    void attemptChunkRecovery(event.reason, 'global');
  };

  window.addEventListener('error', handleWindowError);
  window.addEventListener('unhandledrejection', handleUnhandledRejection);

  return () => {
    window.removeEventListener('error', handleWindowError);
    window.removeEventListener('unhandledrejection', handleUnhandledRejection);
  };
};

export const clearLazyRetryQueryParam = () => {
  if (typeof window === 'undefined') return;

  const url = new URL(window.location.href);
  if (!url.searchParams.has(RETRY_QUERY_PARAM)) return;

  url.searchParams.delete(RETRY_QUERY_PARAM);
  window.history.replaceState({}, '', url.toString());
};

export const lazyWithRetry = <T extends React.ComponentType<any>>(
  importer: () => Promise<{ default: T }>,
  chunkName: string
) => lazy(async () => {
  const retryKey = `${LAZY_RETRY_PREFIX}:${chunkName}`;

  try {
    const module = await importer();

    if (typeof window !== 'undefined') {
      sessionStorage.removeItem(retryKey);
    }

    return module;
  } catch (error) {
    if (await attemptChunkRecovery(error, chunkName)) {
      return new Promise<never>(() => {});
    }

    if (typeof window !== 'undefined') {
      sessionStorage.removeItem(retryKey);
    }

    throw error;
  }
});
